    height: 160px;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 0.85rem;
    text-align: center;
    padding: 1rem;
}

.product-info {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    flex: 1;
}

.product-name {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
}

.product-price {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #198754;
}

.product-rating {
    color: #ffc107;
    font-size: 1.1rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: white;
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    width: fit-content;
}

.btn-add-to-cart {
    margin-top: auto;
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

